import StageTrackerDelivery from '../components/StageTrackerDelivery.jsx';
import SendAssessmentModal from '../components/SendAssessmentModal.jsx';
import CandidateAssessments from '../components/CandidateAssessments.jsx';
import { toast, useConfirm, SkeletonBlock } from '../components/EnterpriseFeedback.jsx';
import { apiGet, apiPost } from '../api.js';
import { getCurrentRole } from '../roleAccess.js';
import '../styles/profile.css';
import '../styles/candidates.css';
import '../styles/candidate_profile.css';
import jsPDF from 'jspdf';
import 'jspdf-autotable';
import { Document, Packer, Paragraph, TextRun } from 'docx';
import { saveAs } from 'file-saver';
import * as XLSX from 'xlsx';
import { currentReportId, issueReportId } from '../utils/reportId.js';

function formatJdUploadDateTime(value) {
  if (!value) return { date: '—', time: '' };
  const raw = String(value).trim();
  const parsed = new Date(raw.includes('T') ? raw : raw.replace(' ', 'T'));
  if (Number.isNaN(parsed.getTime())) {
    return { date: raw.slice(0, 10) || '—', time: '' };
  }
  const day = String(parsed.getDate()).padStart(2, '0');
  const month = String(parsed.getMonth() + 1).padStart(2, '0');
  const year = parsed.getFullYear();
  const hours = String(parsed.getHours()).padStart(2, '0');
  const minutes = String(parsed.getMinutes()).padStart(2, '0');
  return { date: `${day}/${month}/${year}`, time: `${hours}:${minutes}` };
}

function CandidateProfile() {
  const { candidateId } = useParams();
  const navigate = useNavigate();
  const confirm = useConfirm();
  const [candidate, setCandidate] = useState(null);
  const [timeline, setTimeline] = useState([]);
  const [deleting, setDeleting] = useState(false);
  const [loadError, setLoadError] = useState('');
  const canEditStage = ['recruiter', 'admin'].includes(getCurrentRole());
  const [assessmentOpen, setAssessmentOpen] = useState(false);
  const [assessmentsVersion, setAssessmentsVersion] = useState(0);

  const updateHiringState = async (body) => {
    const { ok, data } = await apiPost(`/api/candidates/${candidateId}/hiring-state`, body);
    if (ok) {
      setCandidate(prev => (prev ? {
        ...prev,
        stage_id: data.stage_id,
        hiring_stage: data.stage_name,
        on_hold: data.on_hold,
        automation_paused: data.automation_paused,
      } : prev));
    } else {
      toast({ type: 'error', message: data.error || 'Could not update hiring state.' });
    }
  };
  const setStage = (stageId) => updateHiringState({ stage_id: stageId || null });
  const toggleHold = () => updateHiringState({ on_hold: !candidate?.on_hold });
  const resumeAutomation = () => updateHiringState({ resume_automation: true });

  // --- REPORT MODAL STATE ---
  const [showModal, setShowModal] = useState(false);
  const [selectedFormat, setSelectedFormat] = useState('pdf');
  const [recipientEmail, setRecipientEmail] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [showEmailInput, setShowEmailInput] = useState(false);

  useEffect(() => {
    setLoadError('');
    apiGet(`/api/candidates/${candidateId}`)
      .then(data => {
        const row = data.candidate || null;
        if (!row) {
          setLoadError('Candidate not found.');
          return;
        }
        setCandidate(row);
        setTimeline(data.timeline || []);
      })
      .catch(() => {
        setLoadError('Could not load this candidate. Please check your connection and try again.');
      });
  }, [candidateId]);

  const handleRemove = async () => {
    if (!candidate) return;
    // The profile merges every resume submission for this person; remove them all.
    const ids = candidate.related_candidate_ids?.length ? candidate.related_candidate_ids : [Number(candidateId)];
    const approved = await confirm({
      title: 'Remove candidate',
      message: `Remove candidate "${candidate.name}"${ids.length > 1 ? ` and all ${ids.length} of their resume submissions` : ''} from the repository? This cannot be undone.`,
      confirmLabel: 'Remove Candidate',
      icon: 'fas fa-user-times',
      danger: true,
    });
    if (!approved) return;
    setDeleting(true);
    try {
      const results = await Promise.all(ids.map(id => apiPost(`/api/candidates/${id}/delete`, { confirmed: true })));
      const failed = results.filter(({ ok, data }) => !(ok && data?.success));
      if (!failed.length) {
        toast({ type: 'success', message: 'Candidate removed.' });
        navigate('/talent');
      } else if (failed.length < results.length) {
        toast({ type: 'error', message: `${results.length - failed.length} of ${results.length} submissions removed; the rest could not be removed.` });
        navigate('/talent');
      } else {
        toast({ type: 'error', message: failed[0].data?.error || 'Could not remove candidate.' });
      }
    } catch {
      toast({ type: 'error', message: 'Remove failed. Please try again.' });
    } finally {
      setDeleting(false);
    }
  };

  // ============================================================
  // BUILD REPORT TEXT (for DOCX and Email)
  // ============================================================

  const buildCandidateReportText = () => {
    const now = new Date();
    const dateStr = now.toLocaleDateString('en-US', { 
      year: 'numeric', 
      month: 'long', 
      day: 'numeric' 
    });
    const timeStr = now.toLocaleTimeString('en-US', { 
      hour: '2-digit', 
      minute: '2-digit' 
    });
    
    const sd = candidate?.structured_data || {};
    const aiSummary = candidate?.ai_summary || {};
    const totalExperience = Number(sd.total_experience_years || 0);
    const experienceLabel = totalExperience < 1 ? 'No experience' : `${totalExperience} year${totalExperience === 1 ? '' : 's'}`;
    const matchedSkills = aiSummary.matched_skills || aiSummary.strengths || [];
    const missingSkills = aiSummary.missing_skills || aiSummary.risks || [];
    
    let report = '';
    
    report += '='.repeat(60) + '\n';
    report += '     CANDIDATE EVALUATION REPORT\n';
    report += '='.repeat(60) + '\n\n';
    report += '  Generated on  : ' + dateStr + ' at ' + timeStr + '\n';
    report += '  Report ID     : ' + currentReportId() + '\n\n';
    
    report += '-'.repeat(60) + '\n';
    report += 'CANDIDATE INFORMATION\n';
    report += '-'.repeat(60) + '\n';
    report += '  Name                : ' + (candidate?.name || 'N/A') + '\n';
    report += '  Email               : ' + (candidate?.email || 'N/A') + '\n';
    report += '  Phone               : ' + (candidate?.phone || sd.phone || 'N/A') + '\n';
    report += '  Experience          : ' + experienceLabel + '\n';
    report += '  Location            : ' + (candidate?.location || sd.location || 'N/A') + '\n';
    report += '  Status              : ' + (candidate?.status || 'N/A') + '\n';
    report += '  Hiring Stage        : ' + (candidate?.hiring_stage || 'N/A') + '\n\n';
    
    report += '-'.repeat(60) + '\n';
    report += 'SCREENING SUMMARY\n';
    report += '-'.repeat(60) + '\n';
    report += '  Match Score         : ' + (candidate?.match_score || 0) + '%\n';
    report += '  Recommendation      : ' + (aiSummary.recommendation || 'Review screening evidence') + '\n';
    report += '  Overall Rating      : ' + (candidate?.match_score > 80 ? 'Excellent' : candidate?.match_score > 60 ? 'Good' : 'Needs Review') + '\n\n';
    
    const skills = sd.skills || candidate?.skills || [];
    if (skills.length > 0) {
      report += '-'.repeat(60) + '\n';
      report += 'SKILLS\n';
      report += '-'.repeat(60) + '\n';
      skills.forEach(function(skill) {
        report += '  * ' + skill + '\n';
      });
      report += '\n';
    }
    
    if (matchedSkills.length > 0 || missingSkills.length > 0) {
      report += '-'.repeat(60) + '\n';
      report += 'STRENGTHS & MISSING SKILLS\n';
      report += '-'.repeat(60) + '\n';
      if (matchedSkills.length > 0) {
        report += '  Strengths       : ' + matchedSkills.join(', ') + '\n';
      }
      if (missingSkills.length > 0) {
        report += '  Missing Skills  : ' + missingSkills.join(', ') + '\n';
      }
      report += '\n';
    }
    
    if (sd.education) {
      report += '-'.repeat(60) + '\n';
      report += 'EDUCATION\n';
      report += '-'.repeat(60) + '\n';
      report += '  Degree              : ' + (sd.education.degree || 'N/A') + '\n';
      report += '  Field of Study      : ' + (sd.education.field || 'N/A') + '\n';
      report += '  Institution         : ' + (sd.education.institution || 'N/A') + '\n';
      report += '  Graduation Year     : ' + (sd.education.graduation_year || 'N/A') + '\n\n';
    }
    
    const workExp = sd.work_experience || [];
    if (workExp.length > 0) {
      report += '-'.repeat(60) + '\n';
      report += 'WORK EXPERIENCE\n';
      report += '-'.repeat(60) + '\n';
      workExp.forEach(function(exp, index) {
        report += '  ' + (index + 1) + '. ' + (exp.company || 'N/A') + '\n';
        report += '     Role    : ' + (exp.position || exp.designation || 'N/A') + '\n';
        report += '     Duration: ' + (exp.start_date || '') + (exp.end_date ? ' - ' + exp.end_date : '') + '\n';
      });
      report += '\n';
    }
    
    if (candidate?.jd_history && candidate.jd_history.length > 0) {
      report += '-'.repeat(60) + '\n';
      report += 'APPLIED ROLES\n';
      report += '-'.repeat(60) + '\n';
      candidate.jd_history.forEach(function(jd, index) {
        report += '  ' + (index + 1) + '. ' + jd.jd_title + ' : ' + (jd.match_score || 0) + '% match\n';
      });
      report += '\n';
    }
    
    report += '-'.repeat(60) + '\n';
    report += 'AI CANDIDATE SUMMARY\n';
    report += '-'.repeat(60) + '\n';
    let summaryText = '';
    if (aiSummary.recommendation) {
      summaryText = aiSummary.recommendation;
    } else {
      const name = candidate?.name || 'The candidate';
      const match = candidate?.match_score || 0;
      const skillCount = (sd.skills || candidate?.skills || []).length;
      summaryText = name + ' demonstrates ' + 
        (match > 70 ? 'strong' : match > 50 ? 'moderate' : 'limited') + 
        ' alignment with the applied roles. The candidate has ' + skillCount + 
        ' skills and ' + (matchedSkills.length > 0 ? 'relevant experience' : 'room for skill development') + 
        '. ' + (matchedSkills.length > 0 ? 'Key strengths include ' + matchedSkills.slice(0, 3).join(', ') + '.' : '') +
        (missingSkills.length > 0 ? ' Primary skill gaps: ' + missingSkills.slice(0, 3).join(', ') + '.' : '');
    }
    report += '  ' + summaryText + '\n\n';
    
    report += '='.repeat(60) + '\n';
    report += '  Report generated by Recruitment Analytics System\n';
    report += '  ' + dateStr + ' at ' + timeStr + '\n';
    report += '  Confidential - For internal use only\n';
    report += '='.repeat(60);
    
    return report;
  };

  // ============================================================
  // SIMPLIFIED PDF GENERATION (Working)
  // ============================================================

  const downloadPDF = () => {
  try {
    const reportText = buildCandidateReportText();
    const doc = new jsPDF('p', 'mm', 'a4');
    const margin = 20;
    const maxWidth = doc.internal.pageSize.getWidth() - (margin * 2);
    let y = 20;
    const lines = reportText.split('\n');
    
    lines.forEach(function(line) {
      if (y > 270) {
        doc.addPage();
        y = 20;
      }
      
      if (line.indexOf('CANDIDATE EVALUATION REPORT') !== -1) {
        doc.setFontSize(20);
        doc.setFont('helvetica', 'bold');
        doc.setTextColor(26, 54, 93);
      } else if (line.indexOf('===') !== -1 || line.indexOf('---') !== -1) {
        doc.setFontSize(10);
        doc.setFont('helvetica', 'normal');
        doc.setTextColor(113, 128, 150);
      } else if (line.indexOf('*') !== -1) {
        doc.setFontSize(10);
        doc.setFont('helvetica', 'normal');
        doc.setTextColor(45, 55, 72);
      } else if (line.indexOf(':') !== -1 && line.indexOf('http') === -1) {
        doc.setFontSize(10);
        doc.setFont('helvetica', 'bold');
        doc.setTextColor(45, 55, 72);
      } else {
        doc.setFontSize(10);
        doc.setFont('helvetica', 'normal');
        doc.setTextColor(74, 85, 104);
      }
      
      const x = line.indexOf('*') !== -1 ? margin + 5 : margin;
      const wrappedLines = doc.splitTextToSize(line, maxWidth - (x - margin));
      wrappedLines.forEach(function(wrappedLine) {
        if (y > 270) {
          doc.addPage();
          y = 20;
        }
        doc.text(wrappedLine, x, y);
        y += 6;
      });
      y += 2;
    });
    
    const filename = 'Candidate_Report_' + (candidate?.name || 'candidate').replace(/\s/g, '_') + '_' + new Date().toISOString().split('T')[0] + '.pdf';
    doc.save(filename);
    alert('✅ Candidate Report PDF downloaded successfully!');
    
  } catch (error) {
    console.error('PDF Error:', error);
    alert('❌ Failed to generate PDF. Please try again.');
  }
};

  // ============================================================
  // PROFESSIONAL CSV
  // ============================================================

  const downloadCSV = function() {
    try {
      const sd = candidate?.structured_data || {};
      const aiSummary = candidate?.ai_summary || {};
      const now = new Date();
      const dateStr = now.toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });
      const timeStr = now.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' });
      const matchedSkills = aiSummary.matched_skills || aiSummary.strengths || [];
      const missingSkills = aiSummary.missing_skills || aiSummary.risks || [];

      let csvContent = '';

      csvContent += 'CANDIDATE EVALUATION REPORT\n';
      csvContent += 'Generated: ' + dateStr + ' at ' + timeStr + '\n';
      csvContent += 'Report ID: ' + currentReportId() + '\n\n';

      csvContent += 'CANDIDATE INFORMATION\n';
      csvContent += 'Field,Value\n';
      csvContent += '"Name","' + (candidate?.name || 'N/A') + '"\n';
      csvContent += '"Email","' + (candidate?.email || 'N/A') + '"\n';
      csvContent += '"Phone","' + (candidate?.phone || sd.phone || 'N/A') + '"\n';
      csvContent += '"Experience","' + (sd.total_experience_years || 0) + ' years"\n';
      csvContent += '"Status","' + (candidate?.status || 'N/A') + '"\n';
      csvContent += '"Hiring Stage","' + (candidate?.hiring_stage || 'N/A') + '"\n\n';

      csvContent += 'SCREENING SUMMARY\n';
      csvContent += 'Metric,Value\n';
      csvContent += '"Match Score","' + (candidate?.match_score || 0) + '%"\n';
      csvContent += '"Recommendation","' + (aiSummary.recommendation || 'Review screening evidence') + '"\n';
      csvContent += '"Overall Rating","' + (candidate?.match_score > 80 ? 'Excellent' : candidate?.match_score > 60 ? 'Good' : 'Needs Review') + '"\n\n';

      const skills = sd.skills || candidate?.skills || [];
      if (skills.length > 0) {
        csvContent += 'SKILLS\n';
        csvContent += 'Skill\n';
        skills.forEach(function(skill) {
          csvContent += '"' + skill + '"\n';
        });
        csvContent += '\n';
      }

      if (matchedSkills.length > 0) {
        csvContent += 'STRENGTHS\n';
        csvContent += 'Strength\n';
        matchedSkills.forEach(function(s) {
          csvContent += '"' + s + '"\n';
        });
        csvContent += '\n';
      }
      if (missingSkills.length > 0) {
        csvContent += 'MISSING SKILLS\n';
        csvContent += 'Skill\n';
        missingSkills.forEach(function(s) {
          csvContent += '"' + s + '"\n';
        });
        csvContent += '\n';
      }

      if (sd.education) {
        csvContent += 'EDUCATION\n';
        csvContent += 'Field,Details\n';
        csvContent += '"Degree","' + (sd.education.degree || 'N/A') + '"\n';
        csvContent += '"Field of Study","' + (sd.education.field || 'N/A') + '"\n';
        csvContent += '"Institution","' + (sd.education.institution || 'N/A') + '"\n';
        csvContent += '"Graduation Year","' + (sd.education.graduation_year || 'N/A') + '"\n\n';
      }

      const workExp = sd.work_experience || [];
      if (workExp.length > 0) {
        csvContent += 'WORK EXPERIENCE\n';
        csvContent += 'Company,Role,Duration\n';
        workExp.forEach(function(exp) {
          csvContent += '"' + (exp.company || 'N/A') + '","' + (exp.position || exp.designation || 'N/A') + '","' + (exp.start_date || '') + (exp.end_date ? ' - ' + exp.end_date : '') + '"\n';
        });
        csvContent += '\n';
      }

      if (candidate?.jd_history && candidate.jd_history.length > 0) {
        csvContent += 'APPLIED ROLES\n';
        csvContent += '#,Job Title,Match Score\n';
        candidate.jd_history.forEach(function(jd, index) {
          csvContent += '"' + (index + 1) + '","' + (jd.jd_title || 'N/A') + '","' + (jd.match_score || 0) + '%"\n';
        });
        csvContent += '\n';
      }

      csvContent += 'AI CANDIDATE SUMMARY\n';
      let summaryText = '';
      if (aiSummary.recommendation) {
        summaryText = aiSummary.recommendation;
      } else {
        const name = candidate?.name || 'The candidate';
        const match = candidate?.match_score || 0;
        const skillCount = (sd.skills || candidate?.skills || []).length;
        summaryText = name + ' demonstrates ' + 
          (match > 70 ? 'strong' : match > 50 ? 'moderate' : 'limited') + 
          ' alignment with the applied roles. The candidate has ' + skillCount + 
          ' skills and ' + (matchedSkills.length > 0 ? 'relevant experience' : 'room for skill development') + 
          '. ' + (matchedSkills.length > 0 ? 'Key strengths include ' + matchedSkills.slice(0, 3).join(', ') + '.' : '') +
          (missingSkills.length > 0 ? ' Primary skill gaps: ' + missingSkills.slice(0, 3).join(', ') + '.' : '');
      }
      csvContent += '"Summary","' + summaryText + '"\n\n';

      csvContent += 'Report generated by Recruitment Analytics System\n';
      csvContent += 'Confidential - For internal use only\n';

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = 'Candidate_Report_' + (candidate?.name || 'candidate').replace(/\s/g, '_') + '_' + new Date().toISOString().split('T')[0] + '.csv';
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      alert('✅ Candidate Report CSV downloaded successfully!');
    } catch (error) {
      console.error('CSV Error:', error);
      alert('❌ Failed to generate CSV. Please try again.');
    }
  };

  // ============================================================
  // DOCX GENERATION
  // ============================================================

  const downloadDOCX = async function() {
    try {
      const reportText = buildCandidateReportText();
      const lines = reportText.split('\n');
      const children = [];
      
      lines.forEach(function(line) {
        if (line.trim() === '') {
          children.push(new Paragraph({ spacing: { after: 100 } }));
          return;
        }
        const isBold = line.indexOf(':') !== -1 || 
                      line.indexOf('CANDIDATE EVALUATION REPORT') !== -1 || 
                      line.indexOf('===') !== -1 ||
                      line.indexOf('---') !== -1;
        const isLarge = line.indexOf('CANDIDATE EVALUATION REPORT') !== -1;
        
        children.push(
          new Paragraph({
            children: [new TextRun({ text: line, bold: isBold, size: isLarge ? 32 : 20, font: 'Arial' })],
            spacing: { before: 80, after: 80 },
            indent: { firstLine: line.indexOf('*') !== -1 ? 720 : 0, hanging: line.indexOf('*') !== -1 ? 360 : 0 }
          })
        );
      });
      
      const doc = new Document({
        sections: [{
          properties: { page: { margin: { top: 1440, bottom: 1440, left: 1440, right: 1440 } } },
          children: children
        }]
      });
      
      const blob = await Packer.toBlob(doc);
      const filename = 'Candidate_Report_' + (candidate?.name || 'candidate').replace(/\s/g, '_') + '_' + new Date().toISOString().split('T')[0] + '.docx';
      saveAs(blob, filename);
      alert('✅ Candidate Report DOCX downloaded successfully!');
    } catch (error) {
      console.error('DOCX Error:', error);
      alert('❌ Failed to generate DOCX. Please try again.');
    }
  };

  // ============================================================
  // EXCEL GENERATION
  // ============================================================

  const generateCandidateExcel = () => {
    const now = new Date();
    const dateStr = now.toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });
    const sd = candidate?.structured_data || {};
    const aiSummary = candidate?.ai_summary || {};
    const matchedSkills = aiSummary.matched_skills || aiSummary.strengths || [];
    const missingSkills = aiSummary.missing_skills || aiSummary.risks || [];
    
    const wb = XLSX.utils.book_new();
    
    const detailsData = [
      ['CANDIDATE EVALUATION REPORT'],
      ['Generated: ' + dateStr],
      ['Report ID: ' + currentReportId()],
      [],
      ['CANDIDATE INFORMATION'],
      ['Field', 'Value'],
      ['Name', candidate?.name || 'N/A'],
      ['Email', candidate?.email || 'N/A'],
      ['Phone', candidate?.phone || sd.phone || 'N/A'],
      ['Experience', (sd.total_experience_years || 0) + ' years'],
      ['Status', candidate?.status || 'N/A'],
      ['Hiring Stage', candidate?.hiring_stage || 'N/A'],
      [],
      ['SCREENING SUMMARY'],
      ['Metric', 'Value'],
      ['Match Score', (candidate?.match_score || 0) + '%'],
      ['Recommendation', aiSummary.recommendation || 'Review screening evidence'],
      ['Overall Rating', candidate?.match_score > 80 ? 'Excellent' : candidate?.match_score > 60 ? 'Good' : 'Needs Review']
    ];
    const ws1 = XLSX.utils.aoa_to_sheet(detailsData);
    XLSX.utils.book_append_sheet(wb, ws1, 'Candidate Details');
    
    const skills = sd.skills || candidate?.skills || [];
    const skillsData = [
      ['SKILLS'],
      [],
      ['Skill']
    ];
    skills.forEach(function(skill) {
      skillsData.push([skill]);
    });
    if (skills.length === 0) {
      skillsData.push(['No skills listed']);
    }
    skillsData.push([]);
    skillsData.push(['STRENGTHS']);
    skillsData.push(['Strength']);
    if (matchedSkills.length > 0) {
      matchedSkills.forEach(function(s) {
        skillsData.push([s]);
      });
    } else {
      skillsData.push(['No strengths captured']);
    }
    skillsData.push([]);
    skillsData.push(['MISSING SKILLS']);
    skillsData.push(['Skill']);
    if (missingSkills.length > 0) {
      missingSkills.forEach(function(s) {
        skillsData.push([s]);
      });
    } else {
      skillsData.push(['No missing skills']);
    }
    const ws2 = XLSX.utils.aoa_to_sheet(skillsData);
    XLSX.utils.book_append_sheet(wb, ws2, 'Skills');
    
    const expData = [
      ['EDUCATION'],
      ['Field', 'Details'],
      ['Degree', sd.education?.degree || 'N/A'],
      ['Field of Study', sd.education?.field || 'N/A'],
      ['Institution', sd.education?.institution || 'N/A'],
      ['Graduation Year', sd.education?.graduation_year || 'N/A'],
      [],
      ['WORK EXPERIENCE'],
      ['Company', 'Role', 'Duration']
    ];
    const workExp = sd.work_experience || [];
    if (workExp.length > 0) {
      workExp.forEach(function(exp) {
        expData.push([exp.company || 'N/A', exp.position || exp.designation || 'N/A', (exp.start_date || '') + (exp.end_date ? ' - ' + exp.end_date : '')]);
      });
    } else {
      expData.push(['No work experience listed']);
    }
    const ws3 = XLSX.utils.aoa_to_sheet(expData);
    XLSX.utils.book_append_sheet(wb, ws3, 'Experience');
    
    const rolesData = [
      ['APPLIED ROLES'],
      [],
      ['#', 'Job Title', 'Match Score']
    ];
    if (candidate?.jd_history && candidate.jd_history.length > 0) {
      candidate.jd_history.forEach(function(jd, index) {
        rolesData.push([index + 1, jd.jd_title || 'N/A', (jd.match_score || 0) + '%']);
      });
    } else {
      rolesData.push(['No applied roles']);
    }
    const ws4 = XLSX.utils.aoa_to_sheet(rolesData);
    XLSX.utils.book_append_sheet(wb, ws4, 'Applied Roles');
    
    const summaryData = [
      ['AI CANDIDATE SUMMARY'],
      [],
      ['Summary']
    ];
    let summaryText = '';
    if (aiSummary.recommendation) {
      summaryText = aiSummary.recommendation;
    } else {
      const name = candidate?.name || 'The candidate';
      const match = candidate?.match_score || 0;
      const skillCount = (sd.skills || candidate?.skills || []).length;
      summaryText = name + ' demonstrates ' + 
        (match > 70 ? 'strong' : match > 50 ? 'moderate' : 'limited') + 
        ' alignment with the applied roles. The candidate has ' + skillCount + 
        ' skills and ' + (matchedSkills.length > 0 ? 'relevant experience' : 'room for skill development') + 
        '. ' + (matchedSkills.length > 0 ? 'Key strengths include ' + matchedSkills.slice(0, 3).join(', ') + '.' : '') +
        (missingSkills.length > 0 ? ' Primary skill gaps: ' + missingSkills.slice(0, 3).join(', ') + '.' : '');
    }
    summaryData.push([summaryText]);
    if (aiSummary.interview_focus && aiSummary.interview_focus.length > 0) {
      summaryData.push([]);
      summaryData.push(['Interview Focus Areas']);
      aiSummary.interview_focus.forEach(function(focus) {
        summaryData.push([focus]);
      });
    }
    const ws5 = XLSX.utils.aoa_to_sheet(summaryData);
    XLSX.utils.book_append_sheet(wb, ws5, 'AI Summary');
    
    return wb;
  };

  const downloadExcel = function() {
    try {
      const wb = generateCandidateExcel();
      const wbout = XLSX.write(wb, { bookType: 'xlsx', type: 'array' });
      const blob = new Blob([wbout], { type: 'application/octet-stream' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = 'Candidate_Report_' + (candidate?.name || 'candidate').replace(/\s/g, '_') + '_' + new Date().toISOString().split('T')[0] + '.xlsx';
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      alert('✅ Candidate Report Excel downloaded successfully!');
    } catch (error) {
      console.error('Excel Error:', error);
      alert('❌ Failed to generate Excel. Please try again.');
    }
  };

  // ============================================================
  // SEND EMAIL
  // ============================================================

  const sendEmailReport = async function(email) {
    try {
      const reportText = buildCandidateReportText();
      const doc = new jsPDF('p', 'mm', 'a4');
      const margin = 20;
      const maxWidth = doc.internal.pageSize.getWidth() - (margin * 2);
      let y = 20;
      const lines = reportText.split('\n');
      
      lines.forEach(function(line) {
        if (y > 270) {
          doc.addPage();
          y = 20;
        }
        
        if (line.indexOf('CANDIDATE EVALUATION REPORT') !== -1) {
          doc.setFontSize(20);
          doc.setFont('helvetica', 'bold');
          doc.setTextColor(26, 54, 93);
        } else if (line.indexOf('===') !== -1 || line.indexOf('---') !== -1) {
          doc.setFontSize(10);
          doc.setFont('helvetica', 'normal');
          doc.setTextColor(113, 128, 150);
        } else if (line.indexOf('*') !== -1) {
          doc.setFontSize(10);
          doc.setFont('helvetica', 'normal');
          doc.setTextColor(45, 55, 72);
        } else if (line.indexOf(':') !== -1 && line.indexOf('http') === -1) {
          doc.setFontSize(10);
          doc.setFont('helvetica', 'bold');
          doc.setTextColor(45, 55, 72);
        } else {
          doc.setFontSize(10);
          doc.setFont('helvetica', 'normal');
          doc.setTextColor(74, 85, 104);
        }
        
        const x = line.indexOf('*') !== -1 ? margin + 5 : margin;
        const wrappedLines = doc.splitTextToSize(line, maxWidth - (x - margin));
        wrappedLines.forEach(function(wrappedLine) {
          if (y > 270) {
            doc.addPage();
            y = 20;
          }
          doc.text(wrappedLine, x, y);
          y += 6;
        });
        y += 2;
      });
      
      const pdfBlob = doc.output('blob');
      const reader = new FileReader();
      
      return new Promise(function(resolve, reject) {
        reader.onload = async function() {
          try {
            const base64Data = reader.result.split(',')[1];
            
            const response = await apiPost('/api/report/email', {
              recipient: email,
              subject: 'Candidate Report - ' + (candidate?.name || 'Candidate') + ' - ' + new Date().toISOString().split('T')[0],
              message: 'Please find attached the Candidate Evaluation Report for ' + (candidate?.name || 'the candidate') + ' generated on ' + new Date().toLocaleString() + '.',
              attachment: {
                filename: 'Candidate_Report_' + (candidate?.name || 'candidate').replace(/\s/g, '_') + '_' + new Date().toISOString().split('T')[0] + '.pdf',
                content: base64Data,
                mimeType: 'application/pdf'
              }
            });
            
            if (response.ok) {
              alert('✅ Candidate Report sent successfully to ' + email + '!');
              resolve();
            } else {
              throw new Error(response.data?.error || 'Failed to send email');
            }
          } catch (error) {
            console.error('Email send error:', error);
            alert('❌ Failed to send email. Please check your email settings.');
            reject(error);
          }
        };
        reader.onerror = reject;
        reader.readAsDataURL(pdfBlob);
      });
    } catch (error) {
      console.error('Email Error:', error);
      alert('❌ Failed to prepare email. Please try again.');
    }
  };

  // ============================================================
  // MAIN HANDLER
  // ============================================================

  const handleGenerateReport = async function() {
    if (selectedFormat === 'email' && !recipientEmail) {
      alert('⚠️ Please enter a recipient email address');
      return;
    }

    setIsGenerating(true);

    try {
      await issueReportId('candidate_profile', selectedFormat);
      if (selectedFormat === 'pdf') {
        downloadPDF();
      } else if (selectedFormat === 'docx') {
        await downloadDOCX();
      } else if (selectedFormat === 'csv') {
        downloadCSV();
      } else if (selectedFormat === 'excel') {
        downloadExcel();
      } else if (selectedFormat === 'email') {
        await sendEmailReport(recipientEmail);
      } else {
        alert('Unsupported format');
      }

      setShowModal(false);
      setSelectedFormat('pdf');
      setRecipientEmail('');
      setShowEmailInput(false);

    } catch (error) {
      console.error('Report generation error:', error);
      alert('❌ Failed to generate report. Please try again.');
    } finally {
      setIsGenerating(false);
    }
  };

  // ============================================================
  // MODAL - POSITIONED AT BOTTOM
  // ============================================================

  const ReportModal = function() {
    if (!showModal) return null;

    const formatIcons = {
      pdf: '📄',
      docx: '📝',
      csv: '📊',
      excel: '📈',
      email: '✉️'
    };

    const formatColors = {
      pdf: { border: '#dc2626', bg: '#fef2f2', text: '#dc2626' },
      docx: { border: '#2563eb', bg: '#eff6ff', text: '#2563eb' },
      csv: { border: '#16a34a', bg: '#f0fdf4', text: '#16a34a' },
      excel: { border: '#7c3aed', bg: '#f5f3ff', text: '#7c3aed' },
      email: { border: '#f59e0b', bg: '#fffbeb', text: '#f59e0b' }
    };

    return React.createElement(
      'div',
      {
        style: {
          position: 'fixed',
          top: 0,
          left: 0,
          width: '100%',
          height: '100%',
          background: 'rgba(0, 0, 0, 0.3)',
          backdropFilter: 'blur(2px)',
          zIndex: 99998,
          display: 'flex',
          alignItems: 'flex-end',
          justifyContent: 'center',
          paddingBottom: '80px'
        },
        onClick: function() { setShowModal(false); }
      },
      React.createElement(
        'div',
        {
          style: {
            background: '#ffffff',
            borderRadius: '16px 16px 0 0',
            maxWidth: '480px',
            width: '95%',
            maxHeight: '80vh',
            overflowY: 'auto',
            boxShadow: '0 -10px 40px rgba(0,0,0,0.15)',
            border: '1px solid #e2e8f0',
            animation: 'slideUp 0.3s ease'
          },
          onClick: function(e) { e.stopPropagation(); }
        },
        React.createElement('div', {
          style: {
            padding: '16px 20px 12px 20px',
            borderBottom: '2px solid #e2e8f0',
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center',
            background: '#f8fafc',
            borderRadius: '16px 16px 0 0'
          }
        },
          React.createElement('h2', {
            style: {
              fontSize: '18px',
              fontWeight: '700',
              color: '#0f172a',
              margin: 0,
              display: 'flex',
              alignItems: 'center',
              gap: '8px'
            }
          },
            React.createElement('span', null, '📋'),
            ' Generate Candidate Report'
          ),
          React.createElement('button', {
            onClick: function() { setShowModal(false); },
            style: {
              background: '#e2e8f0',
              border: 'none',
              fontSize: '20px',
              color: '#1e293b',
              cursor: 'pointer',
              padding: '2px 12px',
              borderRadius: '8px',
              lineHeight: '1.6',
              fontWeight: '700'
            }
          }, '✕')
        ),
        React.createElement('div', { style: { padding: '20px' } },
          React.createElement('p', {
            style: {
              color: '#1e293b',
              fontSize: '14px',
              fontWeight: '500',
              margin: '0 0 16px 0'
            }
          }, 'Choose your report format'),
          React.createElement('div', {
            style: {
              display: 'grid',
              gridTemplateColumns: 'repeat(5, 1fr)',
              gap: '8px',
              marginBottom: '16px'
            }
          },
            ['pdf', 'docx', 'csv', 'excel', 'email'].map(function(format) {
              var isActive = selectedFormat === format;
              var colors = formatColors[format];
              return React.createElement('div', {
                key: format,
                onClick: function() {
                  setSelectedFormat(format);
                  setShowEmailInput(format === 'email');
                },
                style: {
                  display: 'flex',
                  flexDirection: 'column',
                  alignItems: 'center',
                  gap: '4px',
                  padding: '10px 6px',
                  border: isActive ? '3px solid ' + colors.border : '3px solid #cbd5e1',
                  borderRadius: '12px',
                  cursor: 'pointer',
                  background: isActive ? colors.bg : '#ffffff',
                  boxShadow: isActive ? '0 0 0 4px ' + colors.bg : 'none'
                }
              },
                React.createElement('span', { style: { fontSize: '22px' } }, formatIcons[format]),
                React.createElement('span', {
                  style: {
                    fontSize: '10px',
                    fontWeight: '700',
                    color: isActive ? colors.text : '#475569',
                    textTransform: 'uppercase'
                  }
                }, format === 'excel' ? 'Excel' : format)
              );
            })
          ),
          showEmailInput ? React.createElement('div', {
            style: {
              marginBottom: '14px',
              padding: '14px',
              background: '#f8fafc',
              borderRadius: '10px',
              border: '2px solid #e2e8f0'
            }
          },
            React.createElement('label', {
              style: {
                display: 'block',
                fontSize: '13px',
                fontWeight: '700',
                color: '#0f172a',
                marginBottom: '6px'
              }
            }, '📧 Recipient Email'),
            React.createElement('input', {
              type: 'email',
              placeholder: 'Enter recipient email',
              value: recipientEmail,
              onChange: function(e) { setRecipientEmail(e.target.value); },
              style: {
                width: '100%',
                padding: '10px 14px',
                border: '2px solid #cbd5e1',
                borderRadius: '8px',
                fontSize: '14px',
                boxSizing: 'border-box',
                background: '#ffffff',
                color: '#0f172a'
              }
            }),
            React.createElement('small', {
              style: {
                display: 'block',
                fontSize: '11px',
                color: '#64748b',
                marginTop: '4px'
              }
            }, 'Report will be sent as a PDF attachment')
          ) : null,
          React.createElement('div', {
            style: {
              padding: '10px 14px',
              background: '#f1f5f9',
              borderRadius: '8px',
              fontSize: '12px',
              color: '#0f172a',
              display: 'flex',
              alignItems: 'center',
              gap: '8px',
              border: '2px solid #e2e8f0'
            }
          },
            React.createElement('span', null, 'ℹ️'),
            React.createElement('span', null, 'Report includes: Candidate Details, Skills, Experience, AI Summary')
          )
        ),
        React.createElement('div', {
          style: {
            padding: '14px 20px 20px 20px',
            borderTop: '2px solid #e2e8f0',
            display: 'flex',
            justifyContent: 'flex-end',
            gap: '10px',
            background: '#f8fafc',
            borderRadius: '0 0 16px 16px'
          }
        },
          React.createElement('button', {
            onClick: function() {
              setShowModal(false);
              setSelectedFormat('pdf');
              setRecipientEmail('');
              setShowEmailInput(false);
            },
            style: {
              padding: '10px 24px',
              borderRadius: '10px',
              fontSize: '14px',
              fontWeight: '700',
              border: '2px solid #cbd5e1',
              cursor: 'pointer',
              background: '#ffffff',
              color: '#1e293b'
            }
          }, 'Cancel'),
          React.createElement('button', {
            onClick: handleGenerateReport,
            disabled: isGenerating,
            style: {
              padding: '10px 28px',
              borderRadius: '10px',
              fontSize: '14px',
              fontWeight: '700',
              border: 'none',
              cursor: isGenerating ? 'not-allowed' : 'pointer',
              background: isGenerating ? '#94a3b8' : '#f97316',
              color: 'white',
              boxShadow: isGenerating ? 'none' : '0 4px 14px rgba(249, 115, 22,0.4)',
              display: 'flex',
              alignItems: 'center',
              gap: '6px',
              opacity: isGenerating ? 0.6 : 1
            }
          }, isGenerating ? '⏳ Generating...' : '📥 Generate')
        )
      )
    );
  };

  if (!candidate && loadError) {
    return (
      <Layout>
        <div className="cp-page">
          <div className="cp-card cp-state" role="alert">
            <i className="fas fa-user-slash" aria-hidden="true" />
            <p>{loadError}</p>
            <button type="button" className="cp-btn cp-btn-ghost" onClick={() => navigate('/talent')}>
              <i className="fas fa-arrow-left" aria-hidden="true" /> Back to Talent
            </button>
          </div>
        </div>
      </Layout>
    );
  }
  if (!candidate) return <Layout><div className="cp-page"><SkeletonBlock variant="profile" count={3} /></div></Layout>;

  const sd = candidate.structured_data || {};
  const totalExperience = Number(sd.total_experience_years || 0);
  const experienceLabel = totalExperience < 1 ? 'Less than a year' : `${totalExperience} year${totalExperience === 1 ? '' : 's'}`;
  const phoneNumber = candidate.phone || sd.phone || '';
  const aiSummary = candidate.ai_summary || {};
  const listOf = value => (Array.isArray(value) ? value : String(value || '').split(/\n|,|;/)).map(v => String(v).trim()).filter(Boolean);
  const matched = listOf(aiSummary.matched_skills || aiSummary.strengths);
  const missing = listOf(aiSummary.missing_skills || aiSummary.risks);
  const focus = listOf(aiSummary.interview_focus);
  const workHistory = Array.isArray(sd.work_experience) ? sd.work_experience : [];
  const skills = listOf(sd.skills);
  const steps = candidate.hiring_process_steps || [];
  const status = String(candidate.status || 'Pending');
  const statusTone = /select|hired|accept/i.test(status) ? 'good' : /reject/i.test(status) ? 'bad' : 'neutral';
  const confidence = Math.max(0, Math.min(100, Number(candidate.confidence_score || 0)));
  const uploadedOn = candidate.uploaded_at ? formatJdUploadDateTime(candidate.uploaded_at).date : '';
  const initialsOf = name => String(name || '?').trim().split(/\s+/).slice(0, 2).map(p => p[0]).join('').toUpperCase();

  const detailRows = [
    ['fa-building', 'Client', candidate.client_name || 'No client'],
    ['fa-envelope', 'Email', candidate.email || 'Not provided'],
    ['fa-phone', 'Phone', phoneNumber || 'Not provided'],
    ['fa-briefcase', 'Experience', experienceLabel],
    ['fa-layer-group', 'Role category', candidate.primary_category || 'Others'],
    ['fa-user-tag', 'Source', candidate.candidate_source || candidate.source_vendor_name || 'Direct'],
    ...(uploadedOn ? [['fa-calendar-plus', 'Added on', uploadedOn]] : []),
  ];

  return (
    <Layout>
      <div className="cp-page">
        <button type="button" className="cp-back" onClick={() => navigate('/talent')}>
          <i className="fas fa-arrow-left" aria-hidden="true" /> Talent
        </button>

        {/* Header */}
        <section className="cp-card cp-hero">
          <div className="cp-hero-main">
            <span className="cp-avatar" aria-hidden="true">{initialsOf(candidate.name)}</span>
            <div className="cp-hero-copy">
              <div className="cp-hero-title">
                <h1>{candidate.name}</h1>
                <span className={`cp-badge ${statusTone}`}>{status}</span>
                {candidate.on_hold && <span className="cp-badge warn"><i className="fas fa-circle-pause" aria-hidden="true" /> On hold</span>}
              </div>
              <p className="cp-hero-sub">
                {[candidate.primary_category || 'Others', experienceLabel, candidate.client_name].filter(Boolean).join(' · ')}
              </p>
              <div className="cp-contact">
                {candidate.email && <a href={`mailto:${candidate.email}`}><i className="far fa-envelope" aria-hidden="true" />{candidate.email}</a>}
                {phoneNumber && <a href={`tel:${phoneNumber}`}><i className="fas fa-phone" aria-hidden="true" />{phoneNumber}</a>}
              </div>
            </div>
          </div>
          <div className="cp-hero-actions">
            {canEditStage && (
              <button type="button" className="cp-btn cp-btn-ghost" onClick={() => setAssessmentOpen(true)}>
                <i className="fas fa-clipboard-question" aria-hidden="true" /> Send assessment
              </button>
            )}
            <button type="button" className="cp-btn cp-btn-primary" onClick={() => setShowModal(true)}>
              <i className="fas fa-file-export" aria-hidden="true" /> Generate report
            </button>
            <button type="button" className="cp-btn cp-btn-danger" disabled={deleting} onClick={handleRemove}
              title="Remove this candidate from the repository">
              {deleting ? <><i className="fas fa-spinner fa-spin" aria-hidden="true" /> Removing…</>
                : <><i className="fas fa-user-xmark" aria-hidden="true" /> Remove</>}
            </button>
          </div>
          <div className="cp-hero-stage">
            <span className="cp-label">Hiring progress</span>
            <StageTrackerDelivery screeningStatus={candidate.screening_status ?? null} steps={steps}
              stageId={candidate.stage_id} hiringStage={candidate.hiring_stage} interviewStage={candidate.interview_stage}
              onHold={Boolean(candidate.on_hold)}
              assessmentStatus={candidate.assessment_status} />
          </div>
        </section>

        <div className="cp-layout">
          {/* Main column */}
          <div className="cp-main">
            <section className="cp-card">
              <header className="cp-card-head"><h2><i className="fas fa-wand-magic-sparkles" aria-hidden="true" /> AI candidate summary</h2></header>
              <div className="cp-callout">
                <strong>Recommendation</strong>
                <p>{aiSummary.recommendation || 'Review the screening evidence below and validate role fit during the interview.'}</p>
              </div>
              <div className="cp-summary-grid">
                {[['Matched skills', matched, 'good', 'No matched skills captured.'],
                  ['Missing skills', missing, 'gap', 'No missing skills captured.'],
                  ['Interview focus', focus, 'neutral', 'Use the screening summary.']].map(([title, items, tone, empty]) => (
                  <div key={title}>
                    <h3>{title}</h3>
                    {items.length ? <div className={`cp-chips ${tone}`}>{items.map(item => <span key={item}>{item}</span>)}</div>
                      : <p className="cp-muted">{empty}</p>}
                  </div>
                ))}
              </div>
            </section>

            <section className="cp-card">
              <header className="cp-card-head">
                <h2><i className="fas fa-clipboard-check" aria-hidden="true" /> Screening results</h2>
                <span className="cp-count">{(candidate.screening_summaries || []).length}</span>
              </header>
              {candidate.screening_summary && <p className="cp-note">{candidate.screening_summary}</p>}
              {candidate.rejection_reason && /reject/i.test(status) && (
                <p className="cp-note bad"><strong>Rejection reason:</strong> {candidate.rejection_reason}</p>
              )}
              {(candidate.screening_summaries || []).length ? (
                <div className="cp-screenings">
                  {candidate.screening_summaries.map((item, i) => {
                    const selected = /select/i.test(item.status || '');
                    const score = Number(item.match_score ?? item.score);
                    return (
                      <article key={`${item.jd_title}-${i}`} className={`cp-screening ${selected ? 'good' : 'bad'}`}>
                        <div className="cp-screening-head">
                          <strong>{item.jd_title || 'Job'}</strong>
                          <span className={`cp-badge ${selected ? 'good' : 'bad'}`}>{item.status || 'Reviewed'}</span>
                        </div>
                        {Number.isFinite(score) && score > 0 && (
                          <div className="cp-score"><div><span style={{ width: `${Math.min(score, 100)}%` }} /></div><b>{score}%</b></div>
                        )}
                        {item.summary && <p>{item.summary}</p>}
                        {item.strengths?.length > 0 && <div className="cp-chips good">{item.strengths.map(s => <span key={s}>{s}</span>)}</div>}
                        {item.gaps?.length > 0 && <div className="cp-chips gap">{item.gaps.map(g => <span key={g}>{g}</span>)}</div>}
                        {item.rejection_reason && !selected && <p className="cp-note bad">{item.rejection_reason}</p>}
                        {item.recommendation && <p className="cp-muted"><strong>Recommendation:</strong> {item.recommendation}</p>}
                      </article>
                    );
                  })}
                </div>
              ) : <p className="cp-empty">No screening results yet.</p>}
            </section>

            {canEditStage && (
              <CandidateAssessments candidateId={candidateId} refreshKey={assessmentsVersion} onSend={() => setAssessmentOpen(true)} />
            )}

            <section className="cp-card">
              <header className="cp-card-head"><h2><i className="fas fa-file-lines" aria-hidden="true" /> Resume</h2></header>
              {candidate.structured_data ? (
                <div className="cp-resume">
                  <div>
                    <h3>Experience <span className="cp-muted">· {experienceLabel}</span></h3>
                    {workHistory.length ? (
                      <ol className="cp-history">
                        {workHistory.map((exp, i) => (
                          <li key={i}>
                            <strong>{exp.position || exp.designation || 'Role not specified'}</strong>
                            <span>{exp.company || 'Company not specified'}</span>
                            {(exp.start_date || exp.end_date) && <small>{[exp.start_date, exp.end_date].filter(Boolean).join(' – ')}</small>}
                          </li>
                        ))}
                      </ol>
                    ) : <p className="cp-muted">No work history captured.</p>}
                  </div>
                  <div>
                    <h3>Education</h3>
                    {sd.education ? (
                      <div className="cp-education">
                        <strong>{sd.education.degree || 'Degree not specified'}</strong>
                        {sd.education.field && <span>{sd.education.field}</span>}
                        <small>{[sd.education.institution, sd.education.graduation_year].filter(Boolean).join(' · ') || 'Institution not specified'}</small>
                      </div>
                    ) : <p className="cp-muted">No education captured.</p>}
                  </div>
                  <div className="cp-resume-skills">
                    <h3>Skills <span className="cp-muted">· {skills.length}</span></h3>
                    {skills.length ? <div className="cp-chips">{skills.map(skill => <span key={skill}>{skill}</span>)}</div>
                      : <p className="cp-muted">No skills captured.</p>}
                  </div>
                </div>
              ) : <p className="cp-empty">Resume details are not available for this candidate.</p>}
            </section>
          </div>

          {/* Sidebar */}
          <aside className="cp-side">
            <section className="cp-card">
              <header className="cp-card-head"><h2><i className="fas fa-diagram-project" aria-hidden="true" /> Hiring stage</h2></header>
              {steps.length ? (
                <div className="cp-stage">
                  {canEditStage ? (
                    <label>
                      <span className="cp-label">Current stage</span>
                      <select value={candidate.stage_id || ''} onChange={(e) => setStage(e.target.value)}>
                        <option value="">Not started</option>
                        {steps.map(step => <option key={step.id} value={step.id}>{step.name}</option>)}
                      </select>
                    </label>
                  ) : <p><span className="cp-label">Current stage</span><strong>{candidate.hiring_stage || 'Not started'}</strong></p>}
                  {canEditStage && (
                    <div className="cp-stage-actions">
                      <button type="button" className="cp-btn cp-btn-ghost cp-btn-sm" onClick={toggleHold}>
                        <i className={`fas ${candidate.on_hold ? 'fa-circle-play' : 'fa-circle-pause'}`} aria-hidden="true" />
                        {candidate.on_hold ? 'Take off hold' : 'Put on hold'}
                      </button>
                      {candidate.automation_paused && (
                        <button type="button" className="cp-btn cp-btn-ghost cp-btn-sm" onClick={resumeAutomation}>
                          <i className="fas fa-rotate" aria-hidden="true" /> Resume automatic updates
                        </button>
                      )}
                    </div>
                  )}
                  {candidate.automation_paused && <p className="cp-muted">Automatic stage updates are paused for this candidate.</p>}
                </div>
              ) : (
                <p className="cp-muted">
                  {candidate.hiring_stage ? <><strong>{candidate.hiring_stage}</strong><br /></> : null}
                  This job has no hiring process configured, so stages can't be set here.
                </p>
              )}
            </section>

            <section className="cp-card">
              <header className="cp-card-head"><h2><i className="fas fa-id-card" aria-hidden="true" /> Details</h2></header>
              <dl className="cp-details">
                {detailRows.map(([icon, label, value]) => (
                  <div key={label}>
                    <dt><i className={`fas ${icon}`} aria-hidden="true" />{label}</dt>
                    <dd>{value}</dd>
                  </div>
                ))}
              </dl>
            </section>

            <section className="cp-card">
              <header className="cp-card-head"><h2><i className="fas fa-layer-group" aria-hidden="true" /> Role category</h2></header>
              <div className="cp-chips accent">
                <span>{candidate.primary_category || 'Others'}</span>
                {(candidate.secondary_categories || []).map(category => <span key={category} className="secondary">{category}</span>)}
              </div>
              <div className="cp-confidence">
                <div><span style={{ width: `${confidence}%` }} /></div>
                <small>{confidence}% confidence</small>
              </div>
              <p className="cp-muted">{candidate.category_reason || 'No categorisation reason captured.'}</p>
              {(candidate.matched_keywords || []).length > 0 && (
                <div className="cp-chips small">{candidate.matched_keywords.slice(0, 10).map(k => <span key={k}>{k}</span>)}</div>
              )}
              <p className="cp-meta">
                Source: {candidate.categorization_source || 'resume'}
                {candidate.categorized_date ? ` · Updated ${formatJdUploadDateTime(candidate.categorized_date).date}` : ''}
              </p>
            </section>

            <section className="cp-card">
              <header className="cp-card-head">
                <h2><i className="fas fa-briefcase" aria-hidden="true" /> Applied roles</h2>
                <span className="cp-count">{(candidate.jd_history || []).length}</span>
              </header>
              {(candidate.jd_history || []).length ? (
                <ul className="cp-roles">
                  {candidate.jd_history.map((jd, i) => {
                    const when = formatJdUploadDateTime(jd.comparison_date);
                    const score = Number(jd.match_score || 0);
                    return (
                      <li key={i}>
                        <span>
                          <strong>{jd.jd_title}</strong>
                          <small>{when.date}{when.time ? ` · ${when.time}` : ''}</small>
                        </span>
                        <b className={score >= 70 ? 'good' : score >= 50 ? 'mid' : 'low'}>{score}%</b>
                      </li>
                    );
                  })}
                </ul>
              ) : <p className="cp-muted">Not matched against any job yet.</p>}
            </section>

            <section className="cp-card">
              <header className="cp-card-head"><h2><i className="fas fa-clock-rotate-left" aria-hidden="true" /> Activity</h2></header>
              {timeline.length ? (
                <ol className="cp-timeline">
                  {timeline.map((item, index) => {
                    const stamp = formatJdUploadDateTime(item.date);
                    return (
                      <li key={`${item.type || 'event'}-${index}`} className={`cp-timeline-${item.type || 'event'}`}>
                        <span className="cp-timeline-dot">
                          <i className={item.type === 'interview' ? 'fas fa-calendar-check' : item.type === 'followup' ? 'fas fa-reply' : 'fas fa-clipboard-check'} aria-hidden="true" />
                        </span>
                        <div>
                          <strong>{item.label}</strong>
                          <small>{stamp.date} {stamp.time}{item.status ? ` · ${item.status}` : ''}{item.score !== undefined ? ` · ${item.score}%` : ''}</small>
                          {item.summary && <p>{item.summary}</p>}
                        </div>
                      </li>
                    );
                  })}
                </ol>
              ) : <p className="cp-muted">No activity recorded yet.</p>}
            </section>
          </aside>
        </div>

        {ReportModal()}
        {assessmentOpen && (
          <SendAssessmentModal candidate={{ ...candidate, id: Number(candidateId) }} onClose={() => setAssessmentOpen(false)}
            onSent={() => setAssessmentsVersion(version => version + 1)} />
        )}
        <style>{`
          @keyframes slideUp {
            from { opacity: 0; transform: translateY(30px); }
            to { opacity: 1; transform: translateY(0); }
          }
        `}</style>
      </div>
    </Layout>
  );
}

export default CandidateProfile;
